import { test, expect } from '@playwright/test';

test.describe('API Response Caching', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/api/data');
  });

  test('should cache API response and return instant data on repeat visits', async ({ page }) => {
    // First request - should hit the API
    const response = await page.waitForResponse('**/api/data');
    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data).toBeDefined();

    // Verify data is displayed on the page
    const dataList = page.getByRole('list');
    await expect(dataList).toBeVisible();
    const dataItem = page.getByText('Item 1');
    await expect(dataItem).toBeVisible();

    // Second request - should use cached response
    const cachedResponse = await page.waitForResponse('**/api/data');
    expect(cachedResponse.status()).toBe(200);
    const cachedData = await cachedResponse.json();
    expect(cachedData).toBeDefined();

    // Verify cached data is displayed
    await expect(dataList).toBeVisible();
    await expect(dataItem).toBeVisible();

    // Third request - should still use cached response
    const thirdResponse = await page.waitForResponse('**/api/data');
    expect(thirdResponse.status()).toBe(200);
    const thirdCachedData = await thirdResponse.json();
    expect(thirdCachedData).toBeDefined();

    // Verify cached data is displayed
    await expect(dataList).toBeVisible();
    await expect(dataItem).toBeVisible();
  });

  test('should handle cache invalidation and refresh data', async ({ page }) => {
    // First request - should hit the API
    const response = await page.waitForResponse('**/api/data');
    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data).toBeDefined();

    // Verify data is displayed on the page
    const dataList = page.getByRole('list');
    await expect(dataList).toBeVisible();
    const dataItem = page.getByText('Item 1');
    await expect(dataItem).toBeVisible();

    // Second request - should use cached response
    const cachedResponse = await page.waitForResponse('**/api/data');
    expect(cachedResponse.status()).toBe(200);
    const cachedData = await cachedResponse.json();
    expect(cachedData).toBeDefined();

    // Verify cached data is displayed
    await expect(dataList).toBeVisible();
    await expect(dataItem).toBeVisible();

    // Third request - should use cached response
    const thirdResponse = await page.waitForResponse('**/api/data');
    expect(thirdResponse.status()).toBe(200);
    const thirdCachedData = await thirdResponse.json();
    expect(thirdCachedData).toBeDefined();

    // Verify cached data is displayed
    await expect(dataList).toBeVisible();
    await expect(dataItem).toBeVisible();

    // Clear cache
    await page.route('**/api/data', route => {
      route.abort();
    });

    // Fourth request - should hit the API again
    const fourthResponse = await page.waitForResponse('**/api/data');
    expect(fourthResponse.status()).toBe(200);
    const fourthData = await fourthResponse.json();
    expect(fourthData).toBeDefined();

    // Verify fresh data is displayed
    await expect(dataList).toBeVisible();
    await expect(dataItem).toBeVisible();

    // Verify cache is invalidated
    const cachedData = await page.evaluate(() => localStorage.getItem('api_data'));
    expect(cachedData).toBeNull();
  });
});
